/**
 * @event
 * @name scwin.stkStatTable_oncellclick
 * @author Inswave
 * @date 2026. 09. 29
 * @param rowIndex columnIndex columnId
 * @returns
 * @hidden N
*/
scwin.stkStatTable_oncellclick = async function (rowIndex, columnIndex, columnId) {
    try {
        const dl = $c.util.getComponent('dlt_stokOccrStat');
        if (!dl) { console.error('[sdd] 행 동작 대상 목록 없음: dlt_stokOccrStat'); return; }
        const r = dl.getRowJSON ? dl.getRowJSON(rowIndex) : null;
        if (!r) { return; }
        if (typeof scwin.goAdj === 'function') { await scwin.goAdj(r["isurCd"], r["seq"]); } else { console.error('[sdd] 행 동작 미정의: scwin.goAdj (열 ?)'); await $c.win.alert('이 행 동작을 아직 정하지 못했습니다(전환 미완) — scwin.goAdj'); } return;
    } catch (e) {
        await $c.exception.handleError(e, { notify: 'none', context: 'stkStatTable.oncellclick' });
    }
};

